00061 // ------------------------------------------------------------------------------------------------
00062 // Construction from a 4x4 matrix. The remaining parts of the matrix are ignored.
00063 template <typename TReal>
00064 AI_FORCE_INLINE
00065 aiMatrix3x3t<TReal>::aiMatrix3x3t( const aiMatrix4x4t<TReal>& pMatrix) {
00066     a1 = pMatrix.a1; a2 = pMatrix.a2; a3 = pMatrix.a3;
00067     b1 = pMatrix.b1; b2 = pMatrix.b2; b3 = pMatrix.b3;
00068     c1 = pMatrix.c1; c2 = pMatrix.c2; c3 = pMatrix.c3;
00069 }
00070 
00071 // ------------------------------------------------------------------------------------------------
00072 template <typename TReal>
00073 AI_FORCE_INLINE
00074 aiMatrix3x3t<TReal>& aiMatrix3x3t<TReal>::operator *= (const aiMatrix3x3t<TReal>& m) {
00075     *this = aiMatrix3x3t<TReal>(m.a1 * a1 + m.b1 * a2 + m.c1 * a3,
00076         m.a2 * a1 + m.b2 * a2 + m.c2 * a3,
00077         m.a3 * a1 + m.b3 * a2 + m.c3 * a3,
00078         m.a1 * b1 + m.b1 * b2 + m.c1 * b3,
00079         m.a2 * b1 + m.b2 * b2 + m.c2 * b3,
00080         m.a3 * b1 + m.b3 * b2 + m.c3 * b3,
00081         m.a1 * c1 + m.b1 * c2 + m.c1 * c3,
00082         m.a2 * c1 + m.b2 * c2 + m.c2 * c3,
00083         m.a3 * c1 + m.b3 * c2 + m.c3 * c3);
00084     return *this;
00085 }
00086 
00087 // ------------------------------------------------------------------------------------------------
00088 template <typename TReal>
00089 template <typename TOther>
00090 aiMatrix3x3t<TReal>::operator aiMatrix3x3t<TOther> () const {
00091     return aiMatrix3x3t<TOther>(static_cast<TOther>(a1),static_cast<TOther>(a2),static_cast<TOther>(a3),
00092         static_cast<TOther>(b1),static_cast<TOther>(b2),static_cast<TOther>(b3),
00093         static_cast<TOther>(c1),static_cast<TOther>(c2),static_cast<TOther>(c3));
00094 }
00095 
00096 // ------------------------------------------------------------------------------------------------
00097 template <typename TReal>
00098 AI_FORCE_INLINE
00099 aiMatrix3x3t<TReal> aiMatrix3x3t<TReal>::operator* (const aiMatrix3x3t<TReal>& m) const {
00100     aiMatrix3x3t<TReal> temp( *this);
00101     temp *= m;
00102     return temp;
00103 }
00104 
00105 // ------------------------------------------------------------------------------------------------
00106 template <typename TReal>
00107 AI_FORCE_INLINE
00108 TReal* aiMatrix3x3t<TReal>::operator[] (unsigned int p_iIndex) {
00109     switch ( p_iIndex ) {
00110         case 0:
00111             return &a1;
00112         case 1:
00113             return &b1;
00114         case 2:
00115             return &c1;
00116         default:
00117             break;
00118     }
00119     return &a1;
00120 }
00121 
00122 // ------------------------------------------------------------------------------------------------
00123 template <typename TReal>
00124 AI_FORCE_INLINE
00125 const TReal* aiMatrix3x3t<TReal>::operator[] (unsigned int p_iIndex) const {
00126     switch ( p_iIndex ) {
00127         case 0:
00128             return &a1;
00129         case 1:
00130             return &b1;
00131         case 2:
00132             return &c1;
00133         default:
00134             break;
00135     }
00136     return &a1;
00137 }
00138 
00139 // ------------------------------------------------------------------------------------------------
00140 template <typename TReal>
00141 AI_FORCE_INLINE
00142 bool aiMatrix3x3t<TReal>::operator== (const aiMatrix3x3t<TReal>& m) const {
00143     return a1 == m.a1 && a2 == m.a2 && a3 == m.a3 &&
00144            b1 == m.b1 && b2 == m.b2 && b3 == m.b3 &&
00145            c1 == m.c1 && c2 == m.c2 && c3 == m.c3;
00146 }
00147 
00148 // ------------------------------------------------------------------------------------------------
00149 template <typename TReal>
00150 AI_FORCE_INLINE
00151 bool aiMatrix3x3t<TReal>::operator!= (const aiMatrix3x3t<TReal>& m) const {
00152     return !(*this == m);
00153 }
00154 
00155 // ---------------------------------------------------------------------------
00156 template<typename TReal>
00157 AI_FORCE_INLINE
00158 bool aiMatrix3x3t<TReal>::Equal(const aiMatrix3x3t<TReal>& m, TReal epsilon) const {
00159     return
00160         std::abs(a1 - m.a1) <= epsilon &&
00161         std::abs(a2 - m.a2) <= epsilon &&
00162         std::abs(a3 - m.a3) <= epsilon &&
00163         std::abs(b1 - m.b1) <= epsilon &&
00164         std::abs(b2 - m.b2) <= epsilon &&
00165         std::abs(b3 - m.b3) <= epsilon &&
00166         std::abs(c1 - m.c1) <= epsilon &&
00167         std::abs(c2 - m.c2) <= epsilon &&
00168         std::abs(c3 - m.c3) <= epsilon;
00169 }
00170 
00171 // ------------------------------------------------------------------------------------------------
00172 template <typename TReal>
00173 AI_FORCE_INLINE
00174 aiMatrix3x3t<TReal>& aiMatrix3x3t<TReal>::Transpose() {
00175     // (TReal&) don't remove, GCC complains cause of packed fields
00176     std::swap( (TReal&)a2, (TReal&)b1);
00177     std::swap( (TReal&)a3, (TReal&)c1);
00178     std::swap( (TReal&)b3, (TReal&)c2);
00179     return *this;
00180 }
00181 
00182 // ----------------------------------------------------------------------------------------
00183 template <typename TReal>
00184 AI_FORCE_INLINE
00185 TReal aiMatrix3x3t<TReal>::Determinant() const {
00186     return a1*b2*c3 - a1*b3*c2 + a2*b3*c1 - a2*b1*c3 + a3*b1*c2 - a3*b2*c1;
00187 }
00188 
00189 // ----------------------------------------------------------------------------------------
00190 template <typename TReal>
00191 AI_FORCE_INLINE
00192 aiMatrix3x3t<TReal>& aiMatrix3x3t<TReal>::Inverse() {
00193     // Compute the reciprocal determinant
00194     TReal det = Determinant();
00195     if(det == static_cast<TReal>(0.0))
00196     {
00197         // Matrix not invertible. Setting all elements to nan is not really
00198         // correct in a mathematical sense; but at least qnans are easy to
00199         // spot. XXX we might throw an exception instead, which would
00200         // be even much better to spot :/.
00201         const TReal nan = std::numeric_limits<TReal>::quiet_NaN();
00202         *this = aiMatrix3x3t<TReal>( nan,nan,nan,nan,nan,nan,nan,nan,nan);
00203 
00204         return *this;
00205     }
00206 
00207     TReal invdet = static_cast<TReal>(1.0) / det;
00208 
00209     aiMatrix3x3t<TReal> res;
00210     res.a1 = invdet  * (b2 * c3 - b3 * c2);
00211     res.a2 = -invdet * (a2 * c3 - a3 * c2);
00212     res.a3 = invdet  * (a2 * b3 - a3 * b2);
00213     res.b1 = -invdet * (b1 * c3 - b3 * c1);
00214     res.b2 = invdet  * (a1 * c3 - a3 * c1);
00215     res.b3 = -invdet * (a1 * b3 - a3 * b1);
00216     res.c1 = invdet  * (b1 * c2 - b2 * c1);
00217     res.c2 = -invdet * (a1 * c2 - a2 * c1);
00218     res.c3 = invdet  * (a1 * b2 - a2 * b1);
00219     *this = res;
00220 
00221     return *this;
00222 }
00223 
00224 // ------------------------------------------------------------------------------------------------
00225 template <typename TReal>
00226 AI_FORCE_INLINE
00227 aiMatrix3x3t<TReal>& aiMatrix3x3t<TReal>::RotationZ(TReal a, aiMatrix3x3t<TReal>& out) {
00228     out.a1 = out.b2 = std::cos(a);
00229     out.b1 = std::sin(a);
00230     out.a2 = - out.b1;
00231 
00232     out.a3 = out.b3 = out.c1 = out.c2 = 0.f;
00233     out.c3 = 1.f;
00234 
00235     return out;
00236 }
00237 
00238 // ------------------------------------------------------------------------------------------------
00239 // Returns a rotation matrix for a rotation around an arbitrary axis.
00240 template <typename TReal>
00241 AI_FORCE_INLINE
00242 aiMatrix3x3t<TReal>& aiMatrix3x3t<TReal>::Rotation( TReal a, const aiVector3t<TReal>& axis, aiMatrix3x3t<TReal>& out) {
00243   TReal c = std::cos( a), s = std::sin( a), t = 1 - c;
00244   TReal x = axis.x, y = axis.y, z = axis.z;
00245 
00246   // Many thanks to MathWorld and Wikipedia
00247   out.a1 = t*x*x + c;   out.a2 = t*x*y - s*z; out.a3 = t*x*z + s*y;
00248   out.b1 = t*x*y + s*z; out.b2 = t*y*y + c;   out.b3 = t*y*z - s*x;
00249   out.c1 = t*x*z - s*y; out.c2 = t*y*z + s*x; out.c3 = t*z*z + c;
00250 
00251   return out;
00252 }
00253 
00254 // ------------------------------------------------------------------------------------------------
00255 template <typename TReal>
00256 AI_FORCE_INLINE
00257 aiMatrix3x3t<TReal>& aiMatrix3x3t<TReal>::Translation( const aiVector2t<TReal>& v, aiMatrix3x3t<TReal>& out) {
00258     out = aiMatrix3x3t<TReal>();
00259     out.a3 = v.x;
00260     out.b3 = v.y;
00261     return out;
00262 }
00263 
00264 // ----------------------------------------------------------------------------------------
00273 // ----------------------------------------------------------------------------------------
00274 template <typename TReal>
00275 AI_FORCE_INLINE aiMatrix3x3t<TReal>& aiMatrix3x3t<TReal>::FromToMatrix(const aiVector3t<TReal>& from,
00276         const aiVector3t<TReal>& to, aiMatrix3x3t<TReal>& mtx) {
00277     const TReal e = from * to;
00278     const TReal f = (e < 0)? -e:e;
00279 
00280     if (f > static_cast<TReal>(1.0) - static_cast<TReal>(0.00001))     /* "from" and "to"-vector almost parallel */
00281     {
00282         aiVector3D u,v;     /* temporary storage vectors */
00283         aiVector3D x;       /* vector most nearly orthogonal to "from" */
00284 
00285         x.x = (from.x > 0.0)? from.x : -from.x;
00286         x.y = (from.y > 0.0)? from.y : -from.y;
00287         x.z = (from.z > 0.0)? from.z : -from.z;
00288 
00289         if (x.x < x.y)
00290         {
00291             if (x.x < x.z)
00292             {
00293                 x.x = static_cast<TReal>(1.0);
00294                 x.y = x.z = static_cast<TReal>(0.0);
00295             }
00296             else
00297             {
00298                 x.z = static_cast<TReal>(1.0);
00299                 x.x = x.y = static_cast<TReal>(0.0);
00300             }
00301         }
00302         else
00303         {
00304             if (x.y < x.z)
00305             {
00306                 x.y = static_cast<TReal>(1.0);
00307                 x.x = x.z = static_cast<TReal>(0.0);
00308             }
00309             else
00310             {
00311                 x.z = static_cast<TReal>(1.0);
00312                 x.x = x.y = static_cast<TReal>(0.0);
00313             }
00314         }
00315 
00316         u.x = x.x - from.x; u.y = x.y - from.y; u.z = x.z - from.z;
00317         v.x = x.x - to.x;   v.y = x.y - to.y;   v.z = x.z - to.z;
00318 
00319         const TReal c1_ = static_cast<TReal>(2.0) / (u * u);
00320         const TReal c2_ = static_cast<TReal>(2.0) / (v * v);
00321         const TReal c3_ = c1_ * c2_  * (u * v);
00322 
00323         for (unsigned int i = 0; i < 3; i++)
00324         {
00325             for (unsigned int j = 0; j < 3; j++)
00326             {
00327                 mtx[i][j] =  - c1_ * u[i] * u[j] - c2_ * v[i] * v[j]
00328                     + c3_ * v[i] * u[j];
00329             }
00330             mtx[i][i] += static_cast<TReal>(1.0);
00331         }
00332     }
00333     else  /* the most common case, unless "from"="to", or "from"=-"to" */
00334     {
00335         const aiVector3D v = from ^ to;
00336         /* ... use this hand optimized version (9 mults less) */
00337         const TReal h = static_cast<TReal>(1.0)/(static_cast<TReal>(1.0) + e);      /* optimization by Gottfried Chen */
00338         const TReal hvx = h * v.x;
00339         const TReal hvz = h * v.z;
00340         const TReal hvxy = hvx * v.y;
00341         const TReal hvxz = hvx * v.z;
00342         const TReal hvyz = hvz * v.y;
00343         mtx[0][0] = e + hvx * v.x;
00344         mtx[0][1] = hvxy - v.z;
00345         mtx[0][2] = hvxz + v.y;
00346 
00347         mtx[1][0] = hvxy + v.z;
00348         mtx[1][1] = e + h * v.y * v.y;
00349         mtx[1][2] = hvyz - v.x;
00350 
00351         mtx[2][0] = hvxz - v.y;
00352         mtx[2][1] = hvyz + v.x;
00353         mtx[2][2] = e + hvz * v.z;
00354     }
00355     return mtx;
00356 }
